# ---- Exercise 1 — a list, and the three brackets -------------------------------
# 
session <- list(
  id        = "P042",
  visit     = ___,
  scores    = c(moca = 24, stroop = 118, rt = 455),
  complete  = TRUE
)

str(session)

session["scores"]        # what class is this?
session[["scores"]]      # and this?
class(session[___])
class(session[[___]])

session$scores["moca"]   # reach inside the component

# 
# 
# ---- Exercise 2 — a data frame is a list ---------------------------------------
# 
memclinic <- read.csv("data/memclinic.csv")

typeof(memclinic)      # what is it made of?
class(memclinic)       # what is it labelled as?
length(memclinic)      # rows or columns?
nrow(memclinic)

# The same column, three ways
head(memclinic[["moca"]], 3)
head(memclinic$___, 3)
head(memclinic[, "___"], 3)

# And the container version
class(memclinic["moca"])
class(memclinic[["moca"]])

# 
# 
# ---- Exercise 3 — recoding with control flow -----------------------------------
# 
# A binary flag with the vectorised if
memclinic$flag <- ifelse(memclinic$moca < ___, "positive", "negative")
table(memclinic$flag)

# Three categories, first match wins
memclinic$severity <- dplyr::case_when(
  memclinic$moca >= 26 ~ "___",
  memclinic$moca >= 20 ~ "___",
  TRUE                 ~ "moderate-severe"
)
table(memclinic$severity)

# Why would putting the >= 20 line first be wrong?

# 
# 
# ---- Exercise 4 — write a function ---------------------------------------------
# 
# Write a function that takes a vector of scores and returns how many fall below
# a cut-off, with the cut-off as an argument that defaults to 26.
# 
n_below <- function(x, cutoff = ___) {
  sum(x < cutoff, na.rm = TRUE)
}

n_below(memclinic$moca)
n_below(memclinic$moca, cutoff = ___)

formals(n_below)

# Now break it on purpose: what does this give, and why?
mean(24, 26, 28)
mean(c(24, 26, 28))

# 
# 
# ---- What to take away ---------------------------------------------------------
# 
# - `[` keeps the container, `[[` and `$` open it.
# - A data frame **is** a list of equal-length columns, wearing a class label.
#   `length()` counts columns; use `nrow()` for rows.
# - `if` takes one condition; `ifelse()` and `case_when()` take a whole vector.
# - `case_when()` stops at the first match, so order the conditions from specific
#   to general.
# - A statistical function returns a list — everything in a printed result can be
#   pulled out by name.
# - Check the argument order of a function before you trust its answer.
# 
